mapper.select:
SELECT count(*) totcnt FROM ttokssaemdb.goods goods, ttokssaemdb.branch branch WHERE goods.branchid = branch.branchid
AND goods.branchid = #{session_branchid}
AND goods.goodsname LIKE #{likeQuery}

SELECT R1.* FROM( SELECT branch.branchid, branch.branchname, goods.goodsid, goods.goodsname, goods.type, goods.price, goods.useyn, DATE_FORMAT(goods.regdate, '%Y-%m-%d %H:%i:%s') regdate FROM ttokssaemdb.goods goods, ttokssaemdb.branch branch
AND goods.branchid = branch.branchid
AND goods.branchid = #{session_branchid}
AND goods.goodsname LIKE #{likeQuery}
goods.goodsid goods.goodsname goods.type goods.price goods.useyn goods.regdate ASC ASC DESC
) R1
LIMIT ${length} OFFSET ${start}

SELECT branch.branchid, branch.branchname, goods.goodsid, goods.goodsname, goods.type, goods.price, goods.useyn, DATE_FORMAT(goods.regdate, '%Y-%m-%d %H:%i:%s') regdate FROM ttokssaemdb.goods goods, ttokssaemdb.branch branch
AND goods.branchid = branch.branchid AND goods.goodsid = #{goodsid}
AND goods.branchid = #{session_branchid}

mapper.delete:
